import React, { useEffect, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import { User } from "firebase/auth";
import { getDatabase, ref, get } from "firebase/database";

interface PerfilProps {
  user: User;
}

const dataEjemplo = [
  { semana: "01-07", horas: 5 },
  { semana: "08-14", horas: 12 },
  { semana: "15-21", horas: 7 },
  { semana: "22-28", horas: 13 },
];

// Horarios estilo colegio
const horariosGenerados = [
  {
    día: "Lunes",
    bloques: ["16:00 - 17:00: Matemáticas", "17:00 - 18:00: Historia"],
  },
  {
    día: "Martes",
    bloques: ["18:00 - 19:00: Inglés", "19:00 - 20:00: Programación"],
  },
  {
    día: "Miércoles",
    bloques: ["17:00 - 18:00: Física", "18:00 - 19:00: Literatura"],
  },
  {
    día: "Viernes",
    bloques: ["16:00 - 17:00: Educación Física", "17:00 - 18:00: Taller"],
  },
];

const Perfil: React.FC<PerfilProps> = ({ user }) => {
  const [mesSeleccionado, setMesSeleccionado] = useState("2025-05");
  const [fotoPerfil, setFotoPerfil] = useState<string>(
    "https://i.pravatar.cc/150?img=3"
  );

  useEffect(() => {
    const db = getDatabase();
    const fotoRef = ref(db, `usuarios/${user.uid}/avatar`);

    get(fotoRef).then((snapshot) => {
      if (snapshot.exists()) {
        setFotoPerfil(snapshot.val());
      }
    });
  }, [user.uid]);

  return (
    <div className="flex flex-col md:flex-row gap-6 p-6 bg-neutral-900 text-white min-h-screen">
      {/* Sidebar clásica */}
      <aside className="w-full md:w-1/3 bg-neutral-800 rounded-lg p-4 shadow-lg">
        <img
          src={fotoPerfil}
          alt="Avatar del usuario"
          className="w-32 h-32 rounded-full mx-auto mb-4 shadow-md"
        />
        <div className="space-y-3 text-sm">
          <p>
            <strong>Nombre de Usuario:</strong>
            <br />
            {user.displayName || "Sin nombre"}
          </p>
          <p>
            <strong>ID del Usuario:</strong>
            <br />@{user.uid}
          </p>
          <p>
            <strong>Email:</strong>
            <br />
            {user.email}
          </p>
          <p>
            <strong>Miembro desde:</strong>
            <br />
            {user.metadata?.creationTime
              ? new Date(user.metadata.creationTime).toLocaleDateString()
              : "Desconocido"}
          </p>
        </div>
      </aside>

      {/* Contenido principal */}
      <main className="flex-1 space-y-6">
        <div className="flex items-center gap-4">
          <label htmlFor="mes" className="font-semibold">
            Selecciona el mes:
          </label>
          <input
            id="mes"
            type="month"
            value={mesSeleccionado}
            onChange={(e) => setMesSeleccionado(e.target.value)}
            className="bg-neutral-800 text-white p-2 rounded-md border border-neutral-700"
          />
        </div>

        {/* Horarios escolares */}
        <div className="bg-neutral-800 rounded-lg p-4 shadow-md">
          <h3 className="text-lg font-bold mb-3">Horario semanal generado</h3>
          <div className="space-y-4">
            {horariosGenerados.map((h, i) => (
              <div key={i}>
                <p className="font-semibold text-blue-400">{h.día}</p>
                <ul className="ml-4 list-disc text-sm">
                  {h.bloques.map((bloque, j) => (
                    <li key={j}>{bloque}</li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>

        {/* Gráfico de horas */}
        <div className="bg-neutral-800 rounded-lg p-4 shadow-md">
          <h3 className="text-lg font-bold mb-4">
            Horas jugadas en {mesSeleccionado}
          </h3>
          <div className="w-full h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={dataEjemplo}>
                <XAxis dataKey="semana" stroke="#fff" />
                <YAxis stroke="#fff" />
                <Tooltip
                  contentStyle={{ backgroundColor: "#333", border: "none" }}
                />
                <Bar dataKey="horas" fill="#3b82f6" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </main>
    </div>
  );
};

export default Perfil;
